mapper.select:
SELECT *
FROM t_pay_order


        AND INSTR(order_no, #{query.orderNo})


        AND pay_status = #{query.payStatus}


        AND create_time >= #{query.createTimeBegin}


        AND create_time < DATE_ADD(#{query.createTimeEnd}, INTERVAL 1 DAY)


        AND deleted_flag = #{query.deletedFlag}



    ORDER BY pay_order_id DESC
